["def compute_nCr(n, r):
	C[0][0] = 1
	for i in range(1, n + 1):
		C[i][0] = 1
		for j in range(1, min(i, r) + 1):
			if i != j:
				C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD
			else:
				C[i][j] = 1

def solve(n, m):
	store = [C[m + i - 1][i] for i in range(m + 1)]
	for i in range(1, n + 1):
		s = 1
		for j in range(1, m + 1):
			s = (s + store[j]) % MOD
			store[j] = s * C[m + j - 1][j] % MOD
	return s
