def choose(n, k):
	ntok = 1
	ktok = 1
	for t in xrange(1, min(k, n - k) + 1):
		ntok *= n
		ktok *= t
		n -= 1
	return ntok // ktok

def C(X, M):
	return choose(X + M - 1, M - 1)
