def R(N, M):
	Base = [C(0, M)]
	for i in range(1, M + 1):
		Base.append(Base[i - 1] * (M + i - 1) // i)
	Base = np.array([i % 1000000000 for i in Base], dtype=np.int64)
	Next = Base[:]
	for i in range(1, N):
		Next = np.multiply(Base, np.cumsum(Next) % 1000000000, dtype=np.int64) % 1000000000
	return sum((i for i in Next)) % 1000000000
